import { test } from "node:test";
import assert from "node:assert/strict";
import { EventEmitter } from "node:events";
import { LocationTracker } from "../src/tracking/tracker.ts";
import { RiderSession } from "../src/tracking/sessions.ts";
import { handleDriverPing } from "../src/tracking/pings.ts";

const NOW = 1_763_550_000_000;
const PICKUP = { lat: 52.52, lng: 13.405 };
const near = (i: number) => ({ lat: 52.52 + i * 0.001, lng: 13.405 });

function setup() {
    const bus = new EventEmitter();
    const tracker = new LocationTracker(bus);
    const listeners = () => bus.eventNames().reduce((n, e) => n + bus.listenerCount(e), 0);
    return { bus, tracker, listeners };
}

// A rider connection that records what it was sent, and anything sent after the rider hung up.
function riderSocket() {
    const socket = {
        closed: false,
        messages: [] as { type: string; driverId?: string; etaMinutes?: number }[],
        sentAfterClose: 0,
        send(message: string) {
            if (socket.closed) socket.sentAfterClose++;
            else socket.messages.push(JSON.parse(message));
        },
    };
    return socket;
}

const ping = (driverId: string, i: number, at = NOW) => ({ driverId, position: near(i), at });

test("a rider sees the assigned driver's position with an ETA", () => {
    const { tracker } = setup();
    const socket = riderSocket();
    new RiderSession(tracker, socket, PICKUP).assignDriver("drv-1");
    assert.deepEqual(handleDriverPing(tracker, ping("drv-1", 5), NOW), { accepted: true });
    const locations = socket.messages.filter((m) => m.type === "driver_location");
    assert.equal(locations.length, 1);
    assert.equal(locations[0].etaMinutes, 2);
});

test("a rider who starts watching gets the driver's last known position straight away", () => {
    const { tracker } = setup();
    handleDriverPing(tracker, ping("drv-2", 3), NOW);
    const socket = riderSocket();
    new RiderSession(tracker, socket, PICKUP).assignDriver("drv-2");
    assert.deepEqual(socket.messages.map((m) => m.type), ["driver_assigned", "driver_location"]);
});

test("malformed and stale pings are dropped", () => {
    const { tracker } = setup();
    assert.equal(handleDriverPing(tracker, { driverId: "d", position: { lat: 91, lng: 0 }, at: NOW }, NOW).accepted, false);
    assert.equal(handleDriverPing(tracker, { driverId: "d", position: near(1), at: NOW - 31_000 }, NOW).accepted, false);
    assert.equal(handleDriverPing(tracker, { position: near(1), at: NOW }, NOW).accepted, false);
});

test("after a reassignment the rider only hears from the new driver", () => {
    const { tracker } = setup();
    const socket = riderSocket();
    const session = new RiderSession(tracker, socket, PICKUP);
    session.assignDriver("drv-old");
    session.assignDriver("drv-new");
    tracker.publish(ping("drv-old", 9));
    tracker.publish(ping("drv-new", 2));
    const from = socket.messages.filter((m) => m.type === "driver_location").map((m) => m.driverId);
    console.log("location updates sent to the rider came from:", from);
    assert.deepEqual(from, ["drv-new"]);
});

test("finished trips leave no listeners behind", () => {
    const { tracker, listeners } = setup();
    for (let trip = 0; trip < 200; trip++) {
        const session = new RiderSession(tracker, riderSocket(), PICKUP);
        session.assignDriver(`drv-${trip % 5}`);
        tracker.publish(ping(`drv-${trip % 5}`, trip % 7));
        session.close();
    }
    assert.equal(listeners(), 0, `${listeners()} listeners still registered after 200 finished trips`);
});

test("stopping twice is harmless and the dashboard counts drop to zero", () => {
    const { tracker } = setup();
    const stopA = tracker.watch("drv-3", PICKUP, () => {});
    const stopB = tracker.watch("drv-3", PICKUP, () => {});
    assert.equal(tracker.watcherCount("drv-3"), 2);
    stopA();
    stopA();
    assert.equal(tracker.watcherCount("drv-3"), 1);
    stopB();
    assert.equal(tracker.watcherCount("drv-3"), 0);
});

test("a rider connection is never written to after the session closes", () => {
    const { tracker } = setup();
    const socket = riderSocket();
    const session = new RiderSession(tracker, socket, PICKUP);
    session.assignDriver("drv-4");
    session.close();
    socket.closed = true;
    for (let i = 0; i < 10; i++) tracker.publish(ping("drv-4", i));
    assert.equal(socket.sentAfterClose, 0);
});
